const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const rnd=a=>a[Math.random()*a.length|0];
let timers=[];const stop=()=>{timers.forEach(t=>{clearInterval(t);clearTimeout(t)});timers=[]};
const go=id=>{location.hash=id};
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const init={};let last={};
const pickNew=(k,a)=>{let v;do{v=rnd(a)}while(a.length>1&&v===last[k]);return last[k]=v};
const lsGet=k=>{try{return localStorage.getItem(k)}catch{return null}};
const lsSet=(k,v)=>{try{localStorage.setItem(k,v);return true}catch{return false}};

/* ===== Suara (disintesis, tanpa file; bisa dimatikan) ===== */
let ac=null,sfxOn=true;
const AC=()=>{try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();if(ac.state==="suspended")ac.resume();return ac}catch{return null}};
function tone(f,t=0,d=.4,type="sine",v=.1){const c=AC();if(!c||!sfxOn)return;const o=c.createOscillator(),g=c.createGain(),s=c.currentTime+t;o.type=type;o.frequency.value=f;g.gain.setValueAtTime(v,s);g.gain.exponentialRampToValueAtTime(.001,s+d);o.connect(g);g.connect(c.destination);o.start(s);o.stop(s+d)}
function paper(){const c=AC();if(!c||!sfxOn)return;const n=c.sampleRate*.25,b=c.createBuffer(1,n,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();f.type="bandpass";f.frequency.value=3000;g.gain.value=.15;s.buffer=b;s.connect(f);f.connect(g);g.connect(c.destination);s.start()}
const sfx={click:()=>tone(620,0,.07,"triangle",.07),pop:()=>tone(rnd([523,587,659,784,880]),0,.5,"sine",.1),chime:()=>[1318,1568,2093].forEach((f,i)=>tone(f,i*.12,.7,"sine",.07)),glock:()=>[880,1175,1397,1760].forEach((f,i)=>tone(f,i*.14,.8,"sine",.08))};

/* ===== Mochi ===== */
const mochi=$("#mochi");
let sayId=0;function say(t,m){const s=$("#say");sayId++;s.classList.remove("off");s.textContent=t;s.classList.remove("pop");void s.offsetWidth;s.classList.add("pop");mochi.className=m||"shy"}
mochi.onclick=()=>{setTimeout(()=>mochi.classList.add("boing"),30);say(rnd(["Hehe, geli… 🐰","Mochi malu tapi senang kamu di sini.","Semangat ya, Saskii ♡","Mochi hop hop!"]),"joy");sfx.pop()};
mochi.addEventListener("animationend",e=>{if(e.animationName==="boing")mochi.classList.remove("boing")});
mochi.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();mochi.click()}};

/* ===== Efek ===== */
function burst(x,y,e){if(document.body.classList.contains("calm"))return;for(let i=0;i<7;i++){const s=document.createElement("span");s.textContent=e;s.style.cssText=`position:fixed;left:${x}px;top:${y}px;z-index:40;pointer-events:none`;document.body.append(s);const a=Math.random()*6.28,d=40+Math.random()*60;s.animate([{transform:"translate(0,0)",opacity:1},{transform:`translate(${Math.cos(a)*d}px,${Math.sin(a)*d-30}px)`,opacity:0}],{duration:900}).onfinish=()=>s.remove()}}
function popup(h,cb){const o=document.createElement("div");o.className="ov";o.setAttribute("role","dialog");o.setAttribute("aria-modal","true");o.innerHTML=`<div class="pop glass">${h}<button class="btn main" id="x">Tutup ♡</button></div>`;const k=e=>{if(e.key==="Escape")c()};const c=()=>{o.remove();document.removeEventListener("keydown",k);cb&&cb()};document.addEventListener("keydown",k);o.onclick=e=>{if(e.target===o)c()};$("#x",o).onclick=c;document.body.append(o);$("#x",o).focus()}
function hug(){say("Peluk! 🤗","glow joy");sfx.chime();popup(`<div style="font-size:4rem;line-height:1.2">🤗</div><p class="hand">${esc(rnd(C.hug))}</p>`,()=>say("Hangat, kan? ♡","shy"))}

/* petal rain & cloud */
for(let i=0;i<14;i++){const p=document.createElement("span");p.className="petal";p.style.cssText=`left:${Math.random()*100}%;animation-duration:${10+Math.random()*10}s;animation-delay:${-Math.random()*15}s;transform:scale(${.6+Math.random()*.8})`;$("#sky").append(p)}

/* ===== Navigasi & peta ===== */
