const F=(x,y)=>`<g fill='#5A3A42'><circle cx='${x-6}' cy='${y}' r='1.9'/><circle cx='${x+6}' cy='${y}' r='1.9'/></g><g fill='#ff8fb0' opacity='.75'><ellipse cx='${x-10}' cy='${y+4}' rx='3' ry='2'/><ellipse cx='${x+10}' cy='${y+4}' rx='3' ry='2'/></g><path d='M${x-2.5} ${y+3.5}q2.5 2.5 5 0' fill='none' stroke='#5A3A42' stroke-width='1.6' stroke-linecap='round'/>`;
const B=(c,f)=>{const s=c.map(([x,y,r])=>`<circle cx='${x}' cy='${y}' r='${r}'/>`).join('');return `<g fill='${f}' stroke='#8a5a68' stroke-width='4' stroke-linejoin='round'>${s}</g><g fill='${f}'>${s}</g>`};
