 memories:sv(`<rect x='20' y='13' width='16' height='10' rx='3' fill='#ffc2d6' ${S}/><rect x='8' y='20' width='48' height='34' rx='10' fill='#ffc2d6' ${S}/><circle cx='47' cy='27' r='2.5' fill='#fff6c9'/><circle cx='32' cy='36' r='11' fill='#fff' ${S}/><circle cx='32' cy='36' r='6.5' fill='#cdbaf5'/><circle cx='30' cy='34' r='2' fill='#fff'/><ellipse cx='15' cy='43' rx='3' ry='2' fill='#ff7fab' opacity='.7'/><ellipse cx='49' cy='43' rx='3' ry='2' fill='#ff7fab' opacity='.7'/><path d='M29.5 50q2.5 2.5 5 0' fill='none' stroke='#5A3A42' stroke-width='1.6' stroke-linecap='round'/>`),
 playroom:sv(`<path d='M32 9V3l7 3-7 3' fill='#ffd66b' ${S}/><rect x='12' y='30' width='40' height='25' rx='4' fill='#fff5e1' ${S}/><path d='M5 32L32 9l27 23z' fill='#ffb3c9' ${S}/><path d='M32 9L25 31h14z' fill='#fff'/>`+F(32,43)),
