/* ===== REVISI: Catatan pribadi Saskii di Memory Corner (localStorage, tambah/edit/hapus) ===== */
const MNK="saskii-notes";let mnMem=[],mnEid=null;
const mnLoad=()=>{try{const v=JSON.parse(localStorage.getItem(MNK));return Array.isArray(v)?v:[]}catch{return mnMem}};
const mnStore=a=>{mnMem=a;return lsSet(MNK,JSON.stringify(a))};
function mnRender(newId){const a=mnLoad();
  $("#mynotes").innerHTML=a.length?a.map(n=>`<div class="note mn c${(+n.c||0)%4}${n.id===newId?" new":""}" style="--a:${+n.r||0}deg">${n.t?`<b class="mnt">${esc(n.t)}</b>`:""}<p class="mnb">${esc(n.b)}</p><div class="mnact"><button class="mnbtn" data-me="${esc(n.id)}" aria-label="Edit catatan">Edit</button><button class="mnbtn" data-mx="${esc(n.id)}" aria-label="Hapus catatan">Hapus</button></div></div>`).join(""):`<p class="muted mnempty">Belum ada catatan. Tulis kata-kata kecil yang ingin kamu simpan ♡</p>`}
function mnForm(open){$("#mnform").hidden=!open;$("#mnadd").hidden=open;$("#mnadd").setAttribute("aria-expanded",open);
  if(!open){mnEid=null;$("#mnt").value=$("#mnb").value="";$("#mnmsg").textContent=""}}
$("#mnadd").onclick=()=>{mnForm(true);$("#mnt").focus()};
$("#mncancel").onclick=()=>{mnForm(false);$("#mnadd").focus({preventScroll:true})};
$("#mnsave").onclick=()=>{const t=$("#mnt").value.trim(),b=$("#mnb").value.trim();
  if(!t&&!b){$("#mnmsg").textContent="Tulis sesuatu dulu ya ♡";return}
  const a=mnLoad();let id=mnEid;
  if(id){const n=a.find(x=>x.id===id);if(n){n.t=t;n.b=b}else id=null}
  if(!id){id=String(Date.now());a.unshift({id,t,b,c:Math.random()*4|0,r:+(Math.random()*5-2.5).toFixed(1)})}
  const ok=mnStore(a);mnForm(false);mnRender(id);sfx.pop();
  const el=$(".mn.new");if(el){el.scrollIntoView({block:"nearest"});const r=el.getBoundingClientRect();burst(r.left+r.width/2,r.top+10,"💗")}
  $("#mnadd").focus({preventScroll:true});
  say(ok?"Catatan kecilmu sudah tersimpan ♡":"Catatannya muncul, tapi browser ini belum bisa menyimpannya permanen 🥺",ok?"joy":"sad")};
$("#mynotes").onclick=e=>{const ed=e.target.closest("[data-me]"),dl=e.target.closest("[data-mx]");
  if(ed){const n=mnLoad().find(x=>x.id===ed.dataset.me);if(n){mnForm(true);mnEid=n.id;$("#mnt").value=n.t;$("#mnb").value=n.b;$("#mnmsg").textContent="Sedang mengedit. Tekan Simpan untuk menyimpan.";$("#mnform").scrollIntoView({block:"center"});$("#mnt").focus({preventScroll:true})}}
  if(dl){if(dl.dataset.sure){mnStore(mnLoad().filter(x=>x.id!==dl.dataset.mx));mnRender()}else{dl.dataset.sure=1;dl.textContent="Yakin?";timers.push(setTimeout(()=>{dl.textContent="Hapus";delete dl.dataset.sure},3000))}}};
{const o=init.memories;init.memories=()=>{o();mnForm(false);mnRender()}}
mnRender();

/* Surprise Tree */
function surprise(k,e){const o=$("#sout");if(k==="hug")return hug();
 o.textContent=k==="secret"?C.secret:k==="affirm"?C.affirm[Math.floor(Date.now()/864e5)%C.affirm.length]:pickNew(k,C[k]);
 if(k==="secret"){paper();setTimeout(sfx.chime,300);say(C.micro.secret,"joy")}else sfx.pop();
 o.style.animation="none";o.offsetWidth;o.style.animation="pp .4s";burst(e.clientX,e.clientY,k==="secret"?"💖":"✨")}

/* Diary Café */
const DK="saskii-diary";let eid=null;
const load=()=>{try{return JSON.parse(localStorage.getItem(DK))||[]}catch{return null}};
const store=a=>lsSet(DK,JSON.stringify(a));
function drender(){const a=load(),l=$("#dlist");if(a===null){l.innerHTML="";$("#dmsg").textContent="Maaf, penyimpanan browser sedang tidak tersedia, jadi catatan belum bisa disimpan 🥺";return}
 l.innerHTML=a.length?a.map(e=>`<div class="entry glass"><b>${esc(e.t)||"(tanpa judul)"}</b><br><small class="muted">${esc(e.d)}</small><br>${esc(e.b)}<br><button class="btn sm" data-e="${e.id}">Edit</button> <button class="btn sm" data-x="${e.id}">Delete</button></div>`).join(""):`<p class="muted">${esc(C.micro.diaryEmpty)}</p>`}
init.diary=()=>{eid=null;$("#dt").value=$("#db").value="";$("#dmsg").textContent="";drender()};
$("#dsave").onclick=()=>{const t=$("#dt").value.trim(),b=$("#db").value.trim();if(!t&&!b){$("#dmsg").textContent="Tulis sesuatu dulu ya ♡";return}
 const a=load();if(a===null)return drender();
 if(eid){const e=a.find(x=>x.id===eid);if(e){e.t=t;e.b=b}}else a.unshift({id:String(Date.now()),t,b,d:new Date().toLocaleString("id-ID")});
 $("#dmsg").textContent=store(a)?C.micro.diarySaved:"Gagal menyimpan, penyimpanan browser tidak tersedia.";eid=null;$("#dt").value=$("#db").value="";drender()};
$("#dl").onclick=()=>{const a=load()||[],txt=a.map(e=>`${e.d}\n${e.t}\n${e.b}`).join("\n\n---\n\n")||"(belum ada catatan)";
 try{const u=URL.createObjectURL(new Blob([txt],{type:"text/plain"})),l=document.createElement("a");l.href=u;l.download="diary-saskii.txt";l.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}catch{}
 popup(`<p>Catatanmu, bisa disalin dari sini:</p><textarea rows="8" readonly>${esc(txt)}</textarea>`)};
$("#dlist").onclick=e=>{const a=load()||[],ed=e.target.closest("[data-e]"),dl=e.target.closest("[data-x]");
 if(ed){const x=a.find(v=>v.id===ed.dataset.e);if(x){eid=x.id;$("#dt").value=x.t;$("#db").value=x.b;$("#dt").focus();$("#dmsg").textContent="Sedang mengedit. Tekan Save untuk menyimpan."}}
 if(dl){if(dl.dataset.sure){store(a.filter(v=>v.id!==dl.dataset.x));drender()}else{dl.dataset.sure=1;dl.textContent="Yakin? Klik lagi";timers.push(setTimeout(()=>{dl.textContent="Delete";delete dl.dataset.sure},3000))}}};

/* Closing */
init.closing=()=>{$("#cmsg").textContent=C.closing;sfx.chime();for(let i=0;i<6;i++)timers.push(setTimeout(()=>burst(innerWidth*(.15+i*.14),innerHeight*.4,i%2?"⭐":"💗"),i*250))};

/* Musik latar (opsional, aman jika file belum ada) & kontrol */
/* cadangan: jika browser/halaman memblokir elemen audio, musik dimainkan lewat Web Audio */
function webAudioShim(){const c=AC();if(!c)throw 0;const g=c.createGain();g.connect(c.destination);let buf=null,src=null,busy=false;
 const o={paused:true,get volume(){return g.gain.value},set volume(v){g.gain.value=v},
  async play(){if(!o.paused||busy)return;busy=true;try{if(!buf){const bin=atob(MUSIC.split(",")[1]),u8=Uint8Array.from(bin,x=>x.charCodeAt(0));buf=await c.decodeAudioData(u8.buffer)}
   if(c.state==="suspended")await c.resume();src=c.createBufferSource();src.buffer=buf;src.loop=true;src.connect(g);src.start();o.paused=false;o.onplay&&o.onplay()}finally{busy=false}},
  pause(){if(src){try{src.stop()}catch{}src=null}o.paused=true;o.onpause&&o.onpause()}};return o}
const MUSIC="data:audio/mpeg;base64,";
let au=new Audio(MUSIC);au.loop=true;au.volume=.25;let hasM=true,triedBlob=false,wantPlay=false;
au.addEventListener("error",()=>{if(!triedBlob){triedBlob=true;try{const bin=atob(MUSIC.split(",")[1]),u8=Uint8Array.from(bin,c=>c.charCodeAt(0));au.src=URL.createObjectURL(new Blob([u8],{type:"audio/mpeg"}));return}catch{}}try{const w=webAudioShim();w.volume=+$("#vol").value;w.onplay=w.onpause=au.onplay;au=w;if(wantPlay)au.play().catch(()=>{})}catch{hasM=false;$("#mp").title="Musik tidak bisa dimuat"}});
au.addEventListener("ended",()=>{au.currentTime=0;au.play().catch(()=>{})});
au.onplay=au.onpause=()=>{$("#mp").textContent=au.paused?"▶":"⏸";document.body.classList.toggle("playing",!au.paused)};
$("#mp").onclick=()=>{if(!hasM)return say("Musiknya belum ditambahkan, tapi taman ini tetap hangat ♡");if(au.paused)au.play().catch(()=>{});else{au.pause();say(C.micro.musicOff)}};
$("#vol").oninput=e=>au.volume=+e.target.value;
$("#sf").onclick=()=>{sfxOn=!sfxOn;$("#sf").textContent=sfxOn?"🔔":"🔕";$("#sf").setAttribute("aria-label",sfxOn?"Efek suara aktif":"Efek suara mati")};
$("#cm").onclick=()=>{const c=document.body.classList.toggle("calm");$("#cm").setAttribute("aria-pressed",c)};
$("#start").onclick=()=>{AC();wantPlay=true;if(hasM)au.play().catch(()=>{});sfx.chime();go("map")};

/* foto (tertanam langsung agar tampil juga di versi online) */
const PH={"face": "data:image/jpeg;base64,", "bakery": "data:image/jpeg;base64,","kebaya": "data:image/jpeg;base64,","roti": "data:image/jpeg;base64,","taman": "data:image/jpeg;base64,","mobil": "data:image/jpeg;base64,","golden": "data:image/jpeg;base64,","kebun": "data:image/jpeg;base64,"};
$$("img[data-ph]").forEach(i=>{i.src=PH[i.dataset.ph]});

/* sparkle kursor (desktop saja) */
let lastS=0;addEventListener("pointermove",e=>{if(e.pointerType!=="mouse"||document.body.classList.contains("calm")||matchMedia("(prefers-reduced-motion:reduce)").matches)return;const n=Date.now();if(n-lastS<90)return;lastS=n;const s=document.createElement("span");s.textContent="✦";s.style.cssText=`position:fixed;left:${e.clientX}px;top:${e.clientY}px;z-index:40;pointer-events:none;color:var(--acc);font-size:12px`;document.body.append(s);s.animate([{opacity:1,transform:"scale(1)"},{opacity:0,transform:"translateY(14px) scale(.3)"}],{duration:700}).onfinish=()=>s.remove()});

route();

