/* --- 2. Living Garden: tema & sapaan mengikuti jam perangkat (pagi 5-10, siang 11-14, sore 15-17, malam 18-4) --- */
const hr=()=>new Date().getHours();
const period=h=>h>=5&&h<11?"morning":h>=11&&h<15?"day":h>=15&&h<18?"sunset":"night";
const GREET_PAGI={t:"Good morning, cantik! 🌷☀️",b:"Semoga harimu menyenangkan ya, semoga semua hal baik datang menghampirimu hari ini. Jangan lupa sarapan, jangan terlalu capek, dan jangan lupa senyum. Soalnya kalau kamu senyum, dunia rasanya ikut cerah. Hehehe. 💗"};
const GREET_SORE={t:"Happy afternoon, cantik! 🌻",b:"Gimana harinya? Masih semangat atau sudah mulai lowbat? Hehehe. Jangan lupa istirahat sebentar ya. Semoga sore ini membawa banyak kebahagiaan buat kamu. Kalau capek, jangan lupa istirahat, jangan dipaksakan. Kamu bukan robot, kamu kan manusia gemes. 🤏🏻💗"};
const GREET_MALAM={t:"Good night, pretty girl! 🌙✨",b:"Terima kasih sudah bertahan melewati hari ini. Sekarang waktunya istirahat, jangan terlalu banyak mikirin hal yang belum tentu terjadi ya. Semoga malam ini kamu tidur nyenyak dan mimpi indah. Jangan begadang, nanti bantalnya protes karena kamu ajak ngobrol sampai pagi. Hehehe. Sweet dreams, cantik! 🧸💗"};
const GREET={morning:GREET_PAGI,day:GREET_SORE,sunset:GREET_SORE,night:GREET_MALAM}; /* siang (11-14) memakai sapaan sore */
const THEME={morning:"#FFF4E8",day:"#FFF0F5",sunset:"#FFD9C7",night:"#1b1a33"};
function livingGarden(){const p=period(hr());document.body.dataset.time=p;
 $$(".greet").forEach(e=>{if(e.dataset.p===p)return;e.dataset.p=p;e.textContent="";const g=GREET[p],t=document.createElement("b"),b=document.createElement("span");t.className="gt";t.textContent=g.t;b.className="gb";b.textContent=g.b;e.append(t,b)});
 $('meta[name="theme-color"]').content=THEME[p]}
livingGarden();setInterval(livingGarden,6e4);

/* --- 6. Garden Clock: jam analog (telinga kelinci, tepi bunga) + digital, mengikuti jam perangkat --- */
const CLK_ICON={morning:"☀️",day:"🌤️",sunset:"🌇",night:"🌙"},CLK_NAME={morning:"Pagi",day:"Siang",sunset:"Sore",night:"Malam"};
const CLK_SAY=[t=>`Sekarang jam ${t}, Saskii ♡`,t=>`Jam ${t} nih. Sudah minum air belum? 💧`,t=>`Jam ${t}… pelan-pelan aja yaa 🌸`];
function clockSVG(){
 const cx=100,cy=136;let pet="",tk="";
 for(let i=0;i<12;i++){const a=i*Math.PI/6,sx=Math.sin(a),sy=-Math.cos(a);
  pet+=`<circle class="gc-pet" cx="${(cx+sx*74).toFixed(1)}" cy="${(cy+sy*74).toFixed(1)}" r="15"/>`;
  const x=(cx+sx*52).toFixed(1),y=(cy+sy*52).toFixed(1);
  tk+=i===0?`<path class="gc-tick q" transform="translate(${x} ${y}) scale(1.15)" d="M0 4C-7-1-5-8 0-4C5-8 7-1 0 4Z"/>`:`<circle class="gc-tick${i%3?"":" q"}" cx="${x}" cy="${y}" r="${i%3?2.2:3.6}"/>`}
 return `<svg viewBox="0 0 200 228" aria-hidden="true">
  <g class="gc-ear l"><ellipse class="gc-ear-o" cx="72" cy="40" rx="14" ry="36" transform="rotate(-10 72 40)"/><ellipse class="gc-ear-i" cx="72" cy="42" rx="6" ry="24" transform="rotate(-10 72 42)"/></g>
  <g class="gc-ear r"><ellipse class="gc-ear-o" cx="128" cy="40" rx="14" ry="36" transform="rotate(10 128 40)"/><ellipse class="gc-ear-i" cx="128" cy="42" rx="6" ry="24" transform="rotate(10 128 42)"/></g>
  ${pet}<circle class="gc-rim" cx="${cx}" cy="${cy}" r="64"/>${tk}
  <ellipse class="gc-cheek" cx="70" cy="172" rx="8" ry="5"/><ellipse class="gc-cheek" cx="130" cy="172" rx="8" ry="5"/>
  <ellipse class="gc-eye" cx="84" cy="166" rx="3" ry="4"/><ellipse class="gc-eye" cx="116" cy="166" rx="3" ry="4"/>
  <path class="gc-smile" d="M93 173q7 6 14 0"/>
  <g class="gc-hr" style="transform-origin:${cx}px ${cy}px"><line x1="${cx}" y1="${cy+6}" x2="${cx}" y2="${cy-34}" stroke-width="7"/></g>
  <g class="gc-mn" style="transform-origin:${cx}px ${cy}px"><line x1="${cx}" y1="${cy+8}" x2="${cx}" y2="${cy-50}" stroke-width="4.5"/></g>
  <g class="gc-sc" style="transform-origin:${cx}px ${cy}px"><line x1="${cx}" y1="${cy+14}" x2="${cx}" y2="${cy-54}" stroke-width="2.2" stroke-linecap="round"/><circle cx="${cx}" cy="${cy-54}" r="3.6"/></g>
  <circle class="gc-cap" cx="${cx}" cy="${cy}" r="6.5"/><circle cx="${cx}" cy="${cy}" r="2" fill="#fff"/></svg>`
}
$$(".gclock").forEach(el=>{
 el.tabIndex=0;el.setAttribute("role","button");
 el.innerHTML=`<div class="gc-face">${clockSVG()}</div><div class="gc-info" aria-hidden="true"><div class="gc-time"><span class="gc-h"></span><i class="gc-col">:</i><span class="gc-m"></span><small class="gc-s"></small></div><div class="gc-date hand"></div><span class="gc-per"></span></div>`;
 const talk=()=>{const t=el.dataset.t||"";say(pickNew("ck",CLK_SAY)(t),"joy");const id=sayId;setTimeout(()=>{if(id===sayId){$("#say").classList.add("off");mochi.className="shy"}},6000)};
 el.onclick=talk;el.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();talk()}}
});
const two=n=>String(n).padStart(2,"0");
function tickClock(){
 const els=$$(".gclock");if(!els.length||document.hidden)return;
 const d=new Date(),h=d.getHours(),m=d.getMinutes(),s=d.getSeconds(),p=period(h);
 const ha=(h%12+m/60)*30,ma=(m+s/60)*6,sa=s*6,date=d.toLocaleDateString("id-ID",{weekday:"long",day:"numeric",month:"long"});
 els.forEach(el=>{
  const q=k=>el.querySelector(k),sc=q(".gc-sc");
  q(".gc-hr").style.transform=`rotate(${ha}deg)`;q(".gc-mn").style.transform=`rotate(${ma}deg)`;
  if(s===0){sc.style.transition="none";sc.style.transform="rotate(0deg)";void sc.getBoundingClientRect();sc.style.transition=""}else sc.style.transform=`rotate(${sa}deg)`;
  q(".gc-h").textContent=two(h);q(".gc-m").textContent=two(m);q(".gc-s").textContent=two(s);
  q(".gc-date").textContent=date;q(".gc-per").textContent=`${CLK_ICON[p]} ${CLK_NAME[p]}`;
  const t=`${two(h)}.${two(m)}`;if(el.dataset.t!==t){el.dataset.t=t;el.setAttribute("aria-label",`Jam ${t}, ${date}. Tekan agar Mochi menyebutkan waktu.`)}
 })
}
tickClock();setInterval(tickClock,1000);document.addEventListener("visibilitychange",tickClock);

/* --- 3. Mochi: bubble kontekstual muncul acak tiap 2-5 menit, tampil 8 detik lalu memudar --- */
const MSG={ /* edit kalimat Mochi di sini */
 morning:["Selamat pagi! Sarapan dulu yaa 🍞","Minum air hangat dulu, Saskii ☀️"],
 day:["Udah minum air putih belum? 💧","Makan siang dulu, jangan ditunda yaa 🍚"],
 sunset:["Tarik napas sebentar, kamu sudah kerja keras ☕","Langit sore lagi cantik, coba lihat keluar 🌇"],
 night:["Waktunya relaksasi… pelan-pelan aja ✨","Sudah makan malam belum? 🍲"],
 late:["Udah larut nih, Mochi ngantuk… tidur yuk 🌙","Layarnya diistirahatin dulu ya, Saskii 💤"]};
function mochiTalk(){
 if(document.hidden||$("#breath").classList.contains("on"))return;
 const h=hr();say(pickNew("mt",MSG[h>=22||h<4?"late":period(h)]),"joy");
 const id=sayId;setTimeout(()=>{if(id===sayId){$("#say").classList.add("off");mochi.className="shy"}},8000)
}
const nextTalk=()=>setTimeout(()=>{mochiTalk();nextTalk()},12e4+Math.random()*18e4);
setTimeout(mochiTalk,25e3);nextTalk();

/* --- 4. P3K Emosi: napas 4-7-8 (lingkaran + teks + hitung mundur sinkron) --- */
const BR=[["Tarik napas pelan…",4,1.9],["Tahan dulu…",7,1.9],["Hembuskan perlahan…",8,1]]; /* [teks, detik, skala lingkaran] */
let bInt,bStart,bFocus;
function breathe(i){
 clearInterval(bInt);const [t,s,sc]=BR[i%3],c=$("#bc");
 $("#bt").textContent=t;c.style.transitionDuration=s+"s";c.style.transform=`scale(${sc})`;
 let n=s;$("#bn").textContent=n;
 bInt=setInterval(()=>{if(--n<=0)return breathe(i+1);$("#bn").textContent=n},1000)
}
function openBreath(){
 bFocus=document.activeElement;const c=$("#bc");c.style.transitionDuration="0s";c.style.transform="scale(1)";
 $("#bt").textContent="Siap? Duduk nyaman dulu…";$("#bn").textContent="";
 $("#breath").classList.add("on");bStart=setTimeout(()=>breathe(0),1400);$("#bx").focus({preventScroll:true})
}
function closeBreath(){
 clearInterval(bInt);clearTimeout(bStart);$("#breath").classList.remove("on");
 bFocus&&bFocus.focus&&bFocus.focus({preventScroll:true});say("Hebat, kamu sudah melakukan yang terbaik ♡","shy")
}
$("#sos").onclick=openBreath;$("#bx").onclick=closeBreath;
addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#breath").classList.contains("on"))closeBreath()});

/* --- 5. Mood Soundscape: hanya satu suara aktif; fade in/out halus --- */
const SND={rain:"audio/hujan.mp3",cafe:"audio/kafe.mp3",lofi:"audio/lofi.mp3"}; /* ganti nama file mp3 kamu di sini */
const snd={};let cur=null;
const fade=(a,to,ms,end)=>{clearInterval(a._f);const from=a.volume,t0=Date.now();a._f=setInterval(()=>{const k=Math.min(1,(Date.now()-t0)/ms);a.volume=from+(to-from)*k;if(k===1){clearInterval(a._f);end&&end()}},50)};
const mark=k=>$$(".sb").forEach(b=>{const on=b.dataset.snd===k;b.classList.toggle("on",on);b.setAttribute("aria-pressed",on)});
function playSnd(k){
 const prev=cur;
 if(prev)fade(snd[prev],0,900,()=>{if(cur!==prev)snd[prev].pause()}); /* matikan suara lama */
 if(k===prev){cur=null;return mark(null)}                             /* klik lagi = berhenti */
 const a=snd[k]||(snd[k]=Object.assign(new Audio(SND[k]),{loop:true,volume:0}));
 cur=k;mark(k);if(typeof au!=="undefined")au.pause();                 /* jeda musik latar bawaan */
 a.play().then(()=>fade(a,.5,1500)).catch(()=>{cur=null;mark(null);say("File suaranya belum ketemu. Cek nama file di SND ya ♡","shy")})
}
$$(".sb").forEach(b=>b.onclick=()=>playSnd(b.dataset.snd));
